#' Execute Multi-Year Data Fusion Across ACS Recipient Years
#'
#' @rdname fusionOutput
#' @aliases NULL
#'
#' @description
#' `fusionOutput_multiyear()` is a convenience wrapper around `fusionOutput()` to iteratively run data fusion
#' models across sequential ACS recipient years. The function automatically passes the
#' \code{.fsn} model file generated by the prior year's run to accelerate variable selection
#' and model training for subsequent years.
#'
#' @param acs_years Numeric vector. Sequence of ACS recipient years to process
#'   (e.g., \code{2019:2023}). Must be provided in ascending numeric order.
#'
#' @export

fusionOutput_multiyear <- function(acs_years, ...) {

  # Input validation
  stopifnot(is.numeric(acs_years), length(acs_years) > 0)
  stopifnot(is.character(fusion_vars), length(fusion_vars) > 0)

  if (is.unsorted(acs_years)) {
    stop("`acs_years` must be provided in ascending numeric order (e.g., 2019:2023).", call. = FALSE)
  }

  fsn_paths <- character(length(acs_years))
  names(fsn_paths) <- as.character(acs_years)

  prev_fsn <- NULL
  dots <- list(...)

  for (i in seq_along(acs_years)) {
    current_year <- acs_years[i]
    cli::cat_rule(sprintf("Processing ACS Year: %d (%d of %d)", current_year, i, length(acs_years)))

    # Confirm previous model file exists if not on the first iteration
    if (!is.null(prev_fsn)) {
      if (!file.exists(prev_fsn)) {
        stop(sprintf("Previous .fsn model file not found for year %d: %s", current_year - 1, prev_fsn), call. = FALSE)
      }
      cli::cat_bullet(sprintf("Passing previous model: %s", prev_fsn), bullet = "info")
    } else {
      cli::cat_bullet("Initial year: No prior .fsn model passed.", bullet = "info")
    }

    # Construct a clean language call object to preserve fusionOutput's match.call/logging
    call_list <- c(
      list(
        quote(fusionData::fusionOutput),
        donor = donor,
        fusion_vars = fusion_vars,
        respondent = respondent,
        acs_year = current_year,
        fsn = prev_fsn
      ),
      dots
    )

    # Evaluate as a standard function call syntax
    dir_out <- eval(as.call(call_list))

    # Pattern includes current acs_year: donor_ACSYEAR_RESPONDENT_model.fsn
    target_pattern <- sprintf("%s_%s_%s_model\\.fsn$", donor, current_year, respondent)

    # Locate generated model file directly inside returned output directory
    if (!is.null(dir_out) && dir.exists(dir_out)) {
      candidate_files <- list.files(dir_out, pattern = target_pattern, recursive = TRUE, full.names = TRUE)

      if (length(candidate_files) > 0) {
        # Select the most recently modified .fsn file if multiple exist
        prev_fsn <- candidate_files[which.max(file.info(candidate_files)$mtime)]
        fsn_paths[as.character(current_year)] <- prev_fsn
      } else {
        warning(sprintf("Could not locate generated .fsn file matching pattern '%s' in '%s'.", target_pattern, dir_out))
        prev_fsn <- NULL
      }
    } else {
      warning(sprintf("Output directory returned by fusionOutput() does not exist or is NULL: %s", as.character(dir_out)))
      prev_fsn <- NULL
    }

    gc(verbose = FALSE)
  }

  invisible(fsn_paths)
}
